# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁 velle／volo、volens','愿意；我愿意；愿意的'],['拉丁 voluntas → voluntarius','意愿 → 出于自己意愿的']]
V=B+[['法语 voluntaire → 英语 volunteer','自愿参加的人 → 志愿者；动词主动承担或提供']]
A=B+[['法语 volontaire／拉丁 voluntarius → 英语 voluntary','自愿的、出于意志的']]
W=[
E('volunteer','英 /ˌvɒlənˈtɪə/；美 /ˌvɑːlənˈtɪr/','志愿者；自愿参加、主动承担；主动提供','别人还没硬派给你，你自己举手说“我来”。','名词经法语 voluntaire 接拉丁 voluntarius“自愿的”，早期常指自愿从军者；动词在英语中由名词发展。',V,'a volunteer 常是自愿服务的人。volunteer to help 是主动提出帮忙；volunteer information 则是没人追问也主动说出信息。后一个用法不涉及做公益。volunteer someone for a task 甚至可表示替别人报名，常带“把人推上去”的语气。','volunteer to do；volunteer for；volunteer at；volunteer information。','volunteer 强调主动提出，不等于 accept 接受安排；现代志愿服务常不领工资，但所有历史或动词用法都不能只用“免费”概括。',('Three volunteers stayed to clean the hall.','三位志愿者留下来打扫大厅。'),('She volunteered to take the first shift.','她主动提出值第一班。'),('He did not volunteer any details about the meeting.','他没有主动透露会议的任何细节。'),sources=['https://www.etymonline.com/word/volunteer','https://en.wiktionary.org/wiki/volunteer']),
E('voluntary','英 /ˈvɒləntri/；美 /ˈvɑːlənteri/','自愿的；非强制的；志愿服务的；随意肌相关的','开关由自己的意愿来按，而不是外界强迫你按。','经法语或直接接拉丁 voluntarius，来自 voluntas“意愿”；英语形容词的历史早于 volunteer 动词。',A,'participation is voluntary 表示参加与否由本人选择，voluntary work 常指志愿工作。voluntary movement 则是受意志控制的动作，如主动抬手；这是同一个“自己能决定”向身体控制的延伸。','voluntary participation；voluntary work；a voluntary contribution；voluntary movement。','voluntary 与 compulsory“强制的”相对；optional 也说可选，但 voluntary 更突出自愿。voluntary 不是 voluntary work 以外也都等于无薪。',('Attendance at the workshop is voluntary.','参加这个工作坊是自愿的。'),('She does voluntary work at the local library.','她在当地的图书馆做志愿工作。'),sources=['https://www.etymonline.com/word/voluntary','https://en.wiktionary.org/wiki/voluntary']),
E('voluntarily','英 /ˌvɒlənˈterəli/；美 /ˌvɑːlənˈterəli/','自愿地；主动地','这一步是本人愿意迈出去的。','voluntary 去 y 后接 -ily，形成副词；也有英式前部重读读法 /ˈvɒləntrəli/。',A+[['英语 voluntary → voluntarily','自愿的 → 自愿地行动']],'leave voluntarily 是自愿离开，provide information voluntarily 是主动提供信息。它关注行为是不是出于自己的选择，不自动说明心情很高兴；一个人可以认真权衡后自愿做一件辛苦的事。','participate voluntarily；leave voluntarily；voluntarily disclose；voluntarily agree。','voluntarily 是自愿地，happily 是高兴地，willingly 更侧重愿意接受；语义有交集但不能处处互换。',('All participants joined the project voluntarily.','所有参与者都是自愿加入这个项目的。'),('He voluntarily returned the extra payment.','他主动退回了多付的钱。'),sources=['https://en.wiktionary.org/wiki/voluntarily','https://www.etymonline.com/word/voluntary']),
E('volunteering','英 /ˌvɒlənˈtɪərɪŋ/；美 /ˌvɑːlənˈtɪrɪŋ/','志愿服务；正在自愿参加或主动承担','把时间和精力投入自己愿意帮忙的事情。','volunteer + -ing，既可作分词，也可作表示活动的动名词。',V+[['英语 volunteer + -ing → volunteering','自愿参加这一行动 → 志愿服务活动']],'volunteering at a shelter 是在收容机构做志愿服务；volunteering to lead the discussion 则只是主动承担主持讨论的任务。前一种常作为持续活动，后一种不必属于正式志愿项目。','volunteering opportunities；volunteering at；volunteering for；volunteering to do。','volunteering 是活动，volunteer 是参加的人或动作原形；a volunteering 不常用来数一名志愿者，应说 a volunteer。',('Volunteering at the library helped him meet his neighbors.','在图书馆做志愿服务帮助他结识了邻居。'),('Thank you for volunteering to organize the trip.','谢谢你主动承担组织这次出行的工作。'),sources=['https://en.wiktionary.org/wiki/volunteering','https://www.etymonline.com/word/volunteer']),
E('volunteered','英 /ˌvɒlənˈtɪəd/；美 /ˌvɑːlənˈtɪrd/','主动提出了；自愿参加了；主动提供的','“我来”已经说出口，或信息已经主动给出。','volunteer + -ed，过去式和过去分词；词尾通常读 /d/。',V+[['英语 volunteer + -ed → volunteered','自愿行动或主动提供已经发生']],'she volunteered to help 表示她主动提出帮忙，volunteered information 是主动提供的信息。这个过去式不证明任务已经完成：主动报名与实际干完仍然是两件事。','volunteered to help；volunteered for duty；volunteered information。','volunteered to do 说主动提出做，completed 说已经完成。别把意愿环节直接翻成结果。',('I volunteered to take notes during the meeting.','我主动提出在会上做记录。'),('The witness volunteered a detail that nobody had asked about.','证人主动提供了一个没人问过的细节。'),sources=['https://en.wiktionary.org/wiki/volunteered','https://www.etymonline.com/word/volunteer']),
E('volunteerism','英 /ˌvɒlənˈtɪərɪzəm/；美 /ˌvɑːlənˈtɪrɪzəm/','志愿服务精神；志愿服务的实践或制度','不只一个人偶尔帮忙，而是让自愿参与成为一种持续的做事方式。','volunteer + -ism，早期有志愿从军相关用法，后来广泛用于社区志愿劳动与参与。',V+[['英语 volunteer + -ism → volunteerism','自愿参与的实践、风气或组织方式']],'文章谈 promote volunteerism 时，通常在说鼓励大家持续参与公益或社区服务。它比 volunteering 更适合概括一种文化、趋势或制度安排，而不是某人这个星期去了几次图书馆。','promote volunteerism；a culture of volunteerism；community volunteerism。','volunteering 常说具体活动，volunteerism 常说整体实践或精神。voluntarism 另有哲学等专门含义，别仅按拼写互换。',('The program aims to encourage volunteerism among students.','这个项目旨在鼓励学生参与志愿服务。'),('Volunteerism is an important part of the town’s community life.','志愿服务是这座小城社区生活的重要部分。'),sources=['https://www.etymonline.com/word/volunteerism','https://en.wiktionary.org/wiki/volunteerism'])]
